import{_ as e,c as a,o as t,ah as s}from"./chunks/framework.Dnh4IO1K.js";const u=JSON.parse('{"title":"13、【同人】 離下乾上","description":"周易口訣義 - 13、【同人】 離下乾上","frontmatter":{"title":"13、【同人】 離下乾上","description":"周易口訣義 - 13、【同人】 離下乾上"},"headers":[],"relativePath":"classics/koujueyi/015.md","filePath":"classics/koujueyi/015.md"}'),r={name:"classics/koujueyi/015.md"};function i(o,p,_,c,n,l){return t(),a("div",null,[...p[0]||(p[0]=[s('<h1 id="_13、【同人】-離下乾上" tabindex="-1">13、【同人】 離下乾上 <a class="header-anchor" href="#_13、【同人】-離下乾上" aria-label="Permalink to “13、【同人】 離下乾上”">​</a></h1><p>彖曰：同人，柔得位得中而應乎乾曰「同人」。同人曰</p><p>「同人於野，亨，利涉大川」，乾行也。文明以健，中正而應，君子正也。唯君子為能通天下之志。</p><p>象曰：天與火，同人。君子以類族辨物。</p><p>初九，同人於門，無咎。</p><p>象曰：出門同人，又誰咎也。</p><p>六二：同人於宗，吝。</p><p>象曰：「同人於宗」，吝道也。</p><p>九三：伏戎於莽，升其高陵，三歲不興。</p><p>象曰：「伏戎於莽」，敵剛也。「三歲不興」，安行也。</p><p>九四：乘其墉，弗克攻，吉。</p><p>象曰：「乘其墉」，義弗克也。其吉則困而反則也。</p><p>九五，同人先號啕而後笑，大師克相遇。</p><p>象曰：同人之先，以中直也。大師相遇，言相剋也。</p><p>上九，同人於郊，無悔。</p><p>象曰：「同人於郊」，志未得也。</p><p>解讀</p><p>「同人於野，亨」者，同人者謂和同於人，故曰「同人」也。既與人同，若不廣遠，即不能弘博矣；野者，曠野之所，喻其與人相同，必須廣遠，無所不通，故曰</p><p>「同人於野，亨」也。利涉大川，利君子貞者，既與人同，不憂患難，雖大川亦能濟涉，故曰「利涉大川」也。與人和同，若不以正，則是同於邪妄之道，故曰「君子相同，利以為正，利君子貞」。象曰：「天與火，同人」者，天體高，火炎上，即火勢上逼，以同於天，喻已之同於人也。「君子以類族辨物」者，族，聚也；辨，分也；物，事也。君子以類而聚，君子小人，如有所同，又須分辨事物，各處其道也。</p><p>「初九，同人於門，無咎」者，初九志既弘廣，不拒於物，出門與人同，即無人與之為咎也。</p><p>「六二，同人於宗，吝」者，六二專志在五，所與人同，其意𥚹狹，是鄙吝之道也。</p><p>「九三，伏戎於莽，升其高陵，三歲不興」者，與二相近，而欲親二，故盜憎其主，惡於五，所以潛隱兵戎於草莽之中，將以襲五，故曰「伏戎於莽」也。時升高陵以望前敵，故曰「升其高陵」。以九三之臣而欲拒九五之君，勢不可敵也。縱三年亦不能興起兵眾以侵害於君，故曰「三歲不興」也。</p><p>「九四：乘其墉，弗克攻，吉」者，三處下卦之極，似乘墉牆而不能克敵矣。困罷乃反，以改過修其德，乃獲吉也。</p><p>九五：同人先號啕而後笑，大師克。相遇者，九五所應在二，隔於三、四，不得其應合，乃悲泣也。三四是臣而五是君，以臣拒君，力不可敵，後乃與二相遇，故「後笑」。不能以服物，而以興舉師旅乃克，以明失「同人」之德也。</p><p>上九：同人於郊，無悔者，獨處於外，與人和同，在於郊境之外也。內無其應，無所陵競，未得和同之志，但「無悔」而已。</p>',25)])])}const m=e(r,[["render",i]]);export{u as __pageData,m as default};
